+static_assert(false,
+              "compressor.cpp is only ever compiled into the AVX512+AMX-flagged "
+              "_C target (see cmake/cpu_extension.cmake's VLLM_EXT_SRC_SGL) and "
+              "relies on that unconditionally -- CPU_CAPABILITY_AVX512 must be "
+              "defined here.");
+#endif
