+}  // namespace
+
+at::Tensor fp8_paged_mqa_logits_cpu(at::Tensor& q_fp8, at::Tensor& kvcache_fp8,
+                                    at::Tensor& weight, at::Tensor& seq_lens,
+                                    at::Tensor& page_table, int64_t block_size,
+                                    int64_t max_seq_len) {
