+    U16,
+    I16,
+    U32,
+    I32,
+    U64,
+    I64,
+    F16,
+    Bf16,
+    F32,
+    F64,
+}
+
+impl TensorDtype {
+    pub const fn as_str(self) -> &'static str {
+        match self {
+            Self::Bool => "bool",
+            Self::U8 => "uint8",
+            Self::I8 => "int8",
+            Self::U16 => "uint16",
+            Self::I16 => "int16",
+            Self::U32 => "uint32",
+            Self::I32 => "int32",
+            Self::U64 => "uint64",
+            Self::I64 => "int64",
+            Self::F16 => "float16",
+            Self::Bf16 => "bfloat16",
+            Self::F32 => "float32",
+            Self::F64 => "float64",
+        }
+    }
+
+    pub const fn element_size(self) -> usize {
+        match self {
+            Self::Bool | Self::U8 | Self::I8 => 1,
+            Self::U16 | Self::I16 | Self::F16 | Self::Bf16 => 2,
+            Self::U32 | Self::I32 | Self::F32 => 4,
+            Self::U64 | Self::I64 | Self::F64 => 8,
+        }
+    }
+}
+
+impl fmt::Display for TensorDtype {
+    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
+        f.write_str(self.as_str())
+    }
+}
+
+impl FromStr for TensorDtype {
+    type Err = String;
+
+    fn from_str(value: &str) -> Result<Self, Self::Err> {
+        match value {
+            "bool" => Ok(Self::Bool),
+            "uint8" => Ok(Self::U8),
+            "int8" => Ok(Self::I8),
+            "uint16" => Ok(Self::U16),
+            "int16" => Ok(Self::I16),
+            "uint32" => Ok(Self::U32),
+            "int32" => Ok(Self::I32),
+            "uint64" => Ok(Self::U64),
+            "int64" => Ok(Self::I64),
+            "float16" => Ok(Self::F16),
+            "bfloat16" => Ok(Self::Bf16),
+            "float32" => Ok(Self::F32),
+            "float64" => Ok(Self::F64),
+            _ => Err(format!("unsupported tensor dtype {value:?}")),
+        }
+    }
