+    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
+        let prefix = match self.endianness {
+            Endianness::Native => '=',
+            Endianness::Little => '<',
+            Endianness::Big => '>',
+        };
+        let code = match self.scalar {
+            TensorDtype::Bool => "b1",
+            TensorDtype::U8 => "u1",
+            TensorDtype::I8 => "i1",
+            TensorDtype::U16 => "u2",
+            TensorDtype::I16 => "i2",
+            TensorDtype::U32 => "u4",
+            TensorDtype::I32 => "i4",
+            TensorDtype::U64 => "u8",
+            TensorDtype::I64 => "i8",
+            TensorDtype::F16 => "f2",
+            TensorDtype::F32 => "f4",
+            TensorDtype::F64 => "f8",
+            TensorDtype::Bf16 => "bfloat16",
+        };
