+            Some(b'>') => (Endianness::Big, &dtype[1..]),
+            Some(b'=' | b'|') => (Endianness::Native, &dtype[1..]),
+            _ => (Endianness::Native, dtype),
+        };
+        let scalar = match body {
+            "b1" => TensorDtype::Bool,
+            "u1" => TensorDtype::U8,
+            "i1" => TensorDtype::I8,
+            "u2" => TensorDtype::U16,
+            "i2" => TensorDtype::I16,
+            "u4" => TensorDtype::U32,
+            "i4" => TensorDtype::I32,
+            "u8" => TensorDtype::U64,
+            "i8" => TensorDtype::I64,
+            "f2" => TensorDtype::F16,
+            "f4" => TensorDtype::F32,
+            "f8" => TensorDtype::F64,
+            _ => body.parse().map_err(|_| format!("unsupported dtype string {dtype:?}"))?,
+        };
+        Ok(Self { scalar, endianness })
+    }
